patterns.G002:
Selecto.configure(location_domain(), :mock_connection, validate: false)
|> Selecto.select(["id", "name"])
|> Selecto.filter(
  {:exists, "SELECT 1 FROM regions r WHERE ST_Intersects(selecto_root.geom, r.geom)"}
)
|> Selecto.order_by(asc("id"))

patterns.G004:
Selecto.configure(location_domain(), :mock_connection, validate: false)
|> Selecto.select(["id", "name"])
|> Selecto.filter(
  {:raw_sql_filter, "selecto_root.geom && ST_MakeEnvelope(-74.05, 40.68, -73.90, 40.82, 4326)"}
)
|> Selecto.order_by(asc("id"))

patterns.Q005:
Selecto.configure(attendee_domain_with_orders_join(), :mock_connection, validate: false)
|> Selecto.select(["name", "email"])
|> Selecto.subselect([
  %{fields: ["order_id"], target_schema: :orders, format: :count, alias: "order_count"}
])
|> Selecto.order_by([asc("name")])

patterns.S003:
Selecto.configure(order_domain_with_customer_join(), :mock_connection, validate: false)
|> Selecto.select(["order_number", "status", "total"])
|> Selecto.filter(
  {:exists, "SELECT 1 FROM customers c WHERE c.id = selecto_root.customer_id AND c.tier = 'gold'"}
)
|> Selecto.order_by([desc("total")])
